<?php
namespace App\Http\Controllers;
use App\Models\{Order,OrderItem,Product}; use Illuminate\Http\Request; use Illuminate\Support\Str; use Midtrans\Config; use Midtrans\Snap;
class CheckoutController extends Controller {
 public function show(){ $cart=session('cart',[]);abort_if(empty($cart),302,route('keranjang'));$items=collect($cart)->map(fn($i)=>[$p=Product::find($i['product_id']),$i])->filter(fn($x)=>$x[0])->map(fn($x)=>['product'=>$x[0],'size'=>$x[1]['size'],'color'=>$x[1]['color'],'quantity'=>$x[1]['quantity'],'subtotal'=>$x[0]->price*$x[1]['quantity']]);$subtotal=$items->sum('subtotal');return view('diantar',compact('items','subtotal')); }
 public function pay(Request $r){$data=$r->validate(['shipping_method'=>'required|in:delivery,pickup','address'=>'required_if:shipping_method,delivery|nullable|string','phone'=>'required|string|max:30']);$cart=session('cart',[]);abort_if(empty($cart),422,'Keranjang kosong.');$items=[];$subtotal=0;foreach($cart as $i){$p=Product::lockForUpdate()->findOrFail($i['product_id']);abort_if($i['quantity']>$p->stock,422,'Stok '.$p->name.' tidak mencukupi.');$items[]=[$p,$i];$subtotal+=$p->price*$i['quantity'];}$shipping=$data['shipping_method']==='delivery'?15000:0;$order=\DB::transaction(function()use($data,$items,$subtotal,$shipping){$order=Order::create(['user_id'=>auth()->id(),'order_number'=>'UMI-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'subtotal'=>$subtotal,'shipping_cost'=>$shipping,'total'=>$subtotal+$shipping,'shipping_method'=>$data['shipping_method'],'address'=>$data['address']??null,'phone'=>$data['phone'],'midtrans_order_id'=>'UMI-'.Str::uuid(),'payment_status'=>'pending','status'=>'new']);foreach($items as [$p,$i]){$order->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'size'=>$i['size'],'color'=>$i['color'],'price'=>$p->price,'quantity'=>$i['quantity']]);$p->decrement('stock',$i['quantity']);}return $order;});Config::$serverKey=config('midtrans.server_key');Config::$isProduction=config('midtrans.is_production');Config::$isSanitized=true;Config::$is3ds=true;$token=Snap::getSnapToken(['transaction_details'=>['order_id'=>$order->midtrans_order_id,'gross_amount'=>$order->total],'customer_details'=>['first_name'=>auth()->user()->name,'email'=>auth()->user()->email,'phone'=>$order->phone]]);session()->forget('cart');return response()->json(['snap_token'=>$token,'order_id'=>$order->id,'redirect'=>route('profile.pesanan')]); }
 public function webhook(Request $r){$serverKey=config('midtrans.server_key');$signature=hash('sha512',$r->order_id.$r->status_code.$r->gross_amount.$serverKey);abort_unless(hash_equals($signature,$r->signature_key),403);$o=Order::where('midtrans_order_id',$r->order_id)->first();if(!$o)return response()->json(['ok'=>true]);$status=$r->transaction_status;$o->payment_status=in_array($status,['settlement','capture'])?'paid':($status==='expire'?'expired':$status);if($o->payment_status==='paid'){$o->paid_at=now();$o->status='new';}if($status==='expire'){foreach($o->items as $i)Product::whereKey($i->product_id)->increment('stock',$i->quantity);$o->status='cancelled';}$o->save();return response()->json(['ok'=>true]);}
}
